ar\ntill teamtabellen. Klick på titeln återställer till förstasidan.","tree":{"sha":"a5d13b96665277c447615883e3a637316c95a939","url":"https://api.github.com/repos/Forsakringskassan/rimfrost-portal-handlaggare/git/trees/a5d13b96665277c447615883e3a637316c95a939"},"url":"https://api.github.com/repos/Forsakringskassan/rimfrost-portal-handlaggare/git/commits/fafdb106e5c6e88dc54650edea501a576b1e3d6e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/242170731?v=4","events_url":"https://api.github.com/users/LisaWedin-Ductus/events{/privacy}","followers_url":"https://api.github.com/users/LisaWedin-Ductus/followers","following_url":"https://api.github.com/users/LisaWedin-Ductus/following{/other_user}","gists_url":"https://api.github.com/users/LisaWedin-Ductus/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/LisaWedin-Ductus","id":242170731,"login":"LisaWedin-Ductus","node_id":"U_kgDODm87aw","organizations_url":"https://api.github.com/users/LisaWedin-Ductus/orgs","received_events_url":"https://api.github.com/users/LisaWedin-Ductus/received_events","repos_url":"https://api.github.com/users/LisaWedin-Ductus/repos","site_admin":false,"starred_url":"https://api.github.com/users/LisaWedin-Ductus/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/LisaWedin-Ductus/subscriptions","type":"User","url":"https://api.github.com/users/LisaWedin-Ductus","user_view_type":"public"},"html_url":"https://github.com/Forsakringskassan/rimfrost-portal-handlaggare/commit/fafdb106e5c6e88dc54650edea501a576b1e3d6e","node_id":"C_kwDOQS2wmtoAKGZhZmRiMTA2ZTVjNmU4OGRjNTQ2NTBlZGVhNTAxYTU3NmIxZTNkNmU","parents":[{"html_url":"https://github.com/Forsakringskassan/rimfrost-portal-handlaggare/commit/05ac0bf79013b884ee9da0273a226ba308a97eb8","sha":"05ac0bf79013b884ee9da0273a226ba308a97eb8","url":"https://api.github.com/repos/Forsakringskassan/rimfrost-po