es to ensure they align with the new error handling and routing logic.","tree":{"sha":"ec9a5ad49d428c66bef10b30ea30cde5a603ca2b","url":"https://api.github.com/repos/traoreera/microframe/git/trees/ec9a5ad49d428c66bef10b30ea30cde5a603ca2b"},"url":"https://api.github.com/repos/traoreera/microframe/git/commits/4db5b955787ae19e47ae941b4e9056495a68665f","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/68350805?v=4","events_url":"https://api.github.com/users/traoreera/events{/privacy}","followers_url":"https://api.github.com/users/traoreera/followers","following_url":"https://api.github.com/users/traoreera/following{/other_user}","gists_url":"https://api.github.com/users/traoreera/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/traoreera","id":68350805,"login":"traoreera","node_id":"MDQ6VXNlcjY4MzUwODA1","organizations_url":"https://api.github.com/users/traoreera/orgs","received_events_url":"https://api.github.com/users/traoreera/received_events","repos_url":"https://api.github.com/users/traoreera/repos","site_admin":false,"starred_url":"https://api.github.com/users/traoreera/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/traoreera/subscriptions","type":"User","url":"https://api.github.com/users/traoreera","user_view_type":"public"},"html_url":"https://github.com/traoreera/microframe/commit/4db5b955787ae19e47ae941b4e9056495a68665f","node_id":"C_kwDOQTJFx9oAKDRkYjViOTU1Nzg3YWUxOWU0N2FlOTQxYjRlOTA1NjQ5NWE2ODY2NWY","parents":[{"html_url":"https://github.com/traoreera/microframe/commit/14d68013a7ec8b14910a8bf98a97664ad1b4d990","sha":"14d68013a7ec8b14910a8bf98a97664ad1b4d990","url":"https://api.github.com/repos/traoreera/microframe/commits/14d68013a7ec8b14910a8bf98a97664ad1b4d990"}],"sha":"4db5b955787ae19e47ae941b4e9056495a68665f","url":"https://api.github.com/repos/traoreera/microframe/commits/4db5b955787ae19e47